describe('API Response Caching', () => {
  const API_BASE_URL = 'https://api.example.com';
  const CACHE_DURATION = 5000; // 5 seconds
  let requestCount = 0;

  beforeEach(() => {
    requestCount = 0;
    cy.visit('http://localhost:3000');

    // Intercept API calls to track requests
    cy.intercept('GET', `${API_BASE_URL}/api/data`, (req) => {
      requestCount++;
      req.reply({
        statusCode: 200,
        body: {
          id: 1,
          name: 'Test Data',
          timestamp: new Date().toISOString()
        },
        headers: {
          'Cache-Control': `max-age=${CACHE_DURATION / 1000}`
        }
      });
    }).as('apiCall');
  });

  it('should cache API response and return cached data on repeat visit', () => {
    // First request - should hit the API
    cy.get('[data-testid="fetch-data-btn"]').click();
    cy.wait('@apiCall');
    cy.get('[data-testid="data-display"]').should('contain', 'Test Data');

    const firstRequestCount = requestCount;
    expect(firstRequestCount).to.equal(1);

    // Second request within cache duration - should use cached response
    cy.get('[data-testid="fetch-data-btn"]').click();
    cy.get('[data-testid="data-display"]').should('contain', 'Test Data');

    // Verify no additional API call was made (still 1)
    expect(requestCount).to.equal(firstRequestCount);
  });

  it('should make new API request after cache expires', () => {
    // First request
    cy.get('[data-testid="fetch-data-btn"]').click();
    cy.wait('@apiCall');
    cy.get('[data-testid="data-display"]').should('contain', 'Test Data');

    const firstRequestCount = requestCount;
    expect(firstRequestCount).to.equal(1);

    // Wait for cache to expire
    cy.wait(CACHE_DURATION + 1000);

    // Second request after cache expiration - should hit API again
    cy.get('[data-testid="fetch-data-btn"]').click();
    cy.wait('@apiCall');
    cy.get('[data-testid="data-display"]').should('contain', 'Test Data');

    // Verify new API call was made
    expect(requestCount).to.equal(firstRequestCount + 1);
  });

  it('should handle cache miss gracefully when API fails', () => {
    cy.intercept('GET', `${API_BASE_URL}/api/data`, {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('apiError');

    cy.get('[data-testid="fetch-data-btn"]').click();
    cy.wait('@apiError');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Error');
  });

  it('should display loading state while fetching uncached data', () => {
    cy.intercept('GET', `${API_BASE_URL}/api/data`, (req) => {
      req.reply((res) => {
        res.delay(1000);
      });
    }).as('slowApiCall');

    cy.get('[data-testid="fetch-data-btn"]').click();
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.wait('@slowApiCall');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="data-display"]').should('be.visible');
  });

  it('should clear cache when user clicks clear cache button', () => {
    // First request
    cy.get('[data-testid="fetch-data-btn"]').click();
    cy.wait('@apiCall');

    const firstRequestCount = requestCount;
    expect(firstRequestCount).to.equal(1);

    // Clear cache
    cy.get('[data-testid="clear-cache-btn"]').click();
    cy.get('[data-testid="cache-cleared-message"]').should('be.visible');

    // Second request should hit API again
    cy.get('[data-testid="fetch-data-btn"]').click();
    cy.wait('@apiCall');

    expect(requestCount).to.equal(firstRequestCount + 1);
  });
});
